fun Modifier.drivesPullToRefresh(): Modifier {
    // A no-op scrollable only forwards deltas to nested-scroll ancestors; on desktop the wheel
    // would be swallowed (the list below is a sibling, not a descendant), so touch platforms only.
    if (!isAndroid()) return this
    val noOpScroll = rememberScrollableState { 0f }
    return scrollable(state = noOpScroll, orientation = Orientation.Vertical)
}

